const settings = $input.first().json;
const repository = `${settings.owner.trim()}/${settings.repository.trim()}`;
const timezone = 'Europe/Moscow';
const end = $now.setZone(timezone).startOf('week');
const start = end.minus({ weeks: 1 });
const previousStart = start.minus({ weeks: 1 });
const format = date => date.toUTC().toISO({ suppressMilliseconds: true });
// Completed calendar weeks have stable keys even on manual reruns.
const base = `repo:${repository} is:issue created:${format(start)}..${format(end.minus({ seconds: 1 }))}`;
return [{ json: {
  repository,
  weekStart: start.toISODate(),
  previousWeekStart: previousStart.toISODate(),
  previousPeriod: { start: format(previousStart), end: format(start), endExclusive: true, timezone },
  period: { start: format(start), end: format(end), endExclusive: true, timezone },
  queries: {
    bug: `${base} label:bug`,
    task: `${base} label:task`,
    feature: `${base} label:feature`,
    other: `${base} -label:bug -label:task -label:feature`
  }
} }];

const config = $('Prepare week').first().json;
const sources = [
  ['bug', 'GitHub bugs this week'],
  ['task', 'GitHub tasks this week'],
  ['feature', 'GitHub features this week'],
  ['other', 'GitHub other issues this week']
];
const unique = new Map();
const queryStats = [];
let fetchedRows = 0;
for (const [query, name] of sources) {
  const pages = $(name).all();
  if (!pages.length) throw new Error(`${name}: no response`);
  const ids = new Set();
  const expected = pages[0].json.total_count;
  for (const { json: page } of pages) {
    if (!Array.isArray(page.items) || !Number.isInteger(page.total_count) || page.total_count < 0) {
      throw new Error(`${name}: invalid GitHub response`);
    }
    if (page.incomplete_results !== false || page.total_count > 1000) {
      throw new Error(`${name}: incomplete search results or more than 1000 matches; narrow the period before retrying`);
    }
    if (page.total_count !== expected) throw new Error(`${name}: search results changed during pagination; retry`);
    for (const issue of page.items) {
      if (!Number.isInteger(issue.id)) throw new Error(`${name}: issue without an id`);
      ids.add(issue.id);
      unique.set(issue.id, issue);
      fetchedRows++;
    }
  }
  if (ids.size !== expected) throw new Error(`${name}: expected ${expected} issues, received ${ids.size}; retry`);
  queryStats.push({ query, total: expected, pages: pages.length, fetched: ids.size });
}
const types = ['bug', 'task', 'feature', 'unknown'];
const emptyCounts = () => ({ total: 0, open: 0, closed: 0 });
const byType = new Map(types.map(type => [type, { type, ...emptyCounts() }]));
const byAuthor = new Map();
const issues = [];
const start = Date.parse(config.period.start);
const end = Date.parse(config.period.end);
if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) throw new Error('Invalid reporting period');
let excludedIssues = 0;
for (const issue of unique.values()) {
  const createdAt = Date.parse(issue.created_at);
  if (issue.pull_request || !Number.isFinite(createdAt) || createdAt < start || createdAt >= end) {
    excludedIssues++;
    continue;
  }
  const labels = (issue.labels ?? []).map(label => typeof label === 'string' ? label : label.name).filter(Boolean).map(label => label.toLowerCase());
  const matched = types.filter(type => type !== 'unknown' && labels.includes(type));
  const type = !labels.includes('needs-triage') && matched.length === 1 ? matched[0] : 'unknown';
  const author = issue.user?.login ?? '(deleted user)';
  if (!['open', 'closed'].includes(issue.state)) throw new Error(`Issue #${issue.number}: invalid state`);
  if (!byAuthor.has(author)) byAuthor.set(author, { author, ...emptyCounts(), bug: 0, task: 0, feature: 0, unknown: 0 });
  const typeRow = byType.get(type);
  const authorRow = byAuthor.get(author);
  typeRow.total++;
  typeRow[issue.state]++;
  authorRow.total++;
  authorRow[issue.state]++;
  authorRow[type]++;
  issues.push({ number: issue.number, title: issue.title, url: issue.html_url, author, type, state: issue.state, createdAt: issue.created_at });
}
issues.sort((a, b) => a.number - b.number);
const typeRows = [...byType.values()];
return [{ json: {
  repository: config.repository,
  period: config.period,
  totalIssues: issues.length,
  totalOpen: typeRows.reduce((sum, row) => sum + row.open, 0),
  totalClosed: typeRows.reduce((sum, row) => sum + row.closed, 0),
  byType: typeRows,
  byAuthor: [...byAuthor.values()].sort((a, b) => b.total - a.total || a.author.localeCompare(b.author)),
  queryStats,
  duplicatesRemoved: fetchedRows - unique.size,
  excludedIssues,
  issues
} }];

const current = $('Group weekly statistics').first().json;
const config = $('Prepare week').first().json;
const rows = $input.all().map(item => item.json).filter(row => row.repository !== undefined);
if (rows.length > 1) throw new Error('Несколько записей прошлой недели: удалите дубли repository + week_start');
let previous = null;
if (rows.length) {
  const row = rows[0];
  previous = JSON.parse(row.stats_json);
  if (previous.schemaVersion !== 1 || row.repository !== current.repository || row.week_start !== config.previousWeekStart || previous.repository !== current.repository || previous.weekStart !== config.previousWeekStart) throw new Error('Неверная запись прошлой недели');
  for (const field of ['start', 'end']) {
    if (Date.parse(previous.period?.[field]) !== Date.parse(config.previousPeriod[field]) || Date.parse(row[`period_${field}`]) !== Date.parse(config.previousPeriod[field])) throw new Error('Период прошлой недели не совпадает с ожидаемым');
  }
  for (const [field, column] of [['totalIssues', 'total_issues'], ['totalOpen', 'total_open'], ['totalClosed', 'total_closed']]) {
    if (!Number.isInteger(previous[field]) || previous[field] < 0 || previous[field] !== row[column]) throw new Error('Некорректные итоги прошлой недели');
  }
  if (previous.totalOpen + previous.totalClosed !== previous.totalIssues || !Array.isArray(previous.byType) || !Array.isArray(previous.byAuthor)) throw new Error('Некорректная структура статистики прошлой недели');
  for (const [array, key, fields] of [[previous.byType, 'type', ['total', 'open', 'closed']], [previous.byAuthor, 'author', ['total', 'open', 'closed', 'bug', 'task', 'feature', 'unknown']]]) {
    if (new Set(array.map(row => row[key])).size !== array.length) throw new Error('Повторяющиеся группы в прошлой неделе');
    for (const row of array) {
      if (typeof row[key] !== 'string' || fields.some(field => !Number.isInteger(row[field]) || row[field] < 0) || row.open + row.closed !== row.total) throw new Error('Некорректные группы прошлой недели');
      if (key === 'author' && row.bug + row.task + row.feature + row.unknown !== row.total) throw new Error('Некорректная разбивка автора');
    }
    if (array.reduce((sum, row) => sum + row.total, 0) !== previous.totalIssues) throw new Error('Суммы групп прошлой недели не совпадают с итогами');
  }
  if (previous.byType.length !== 4 || ['bug', 'task', 'feature', 'unknown'].some(type => !previous.byType.some(row => row.type === type))) throw new Error('В прошлой неделе должны быть четыре типа');
}
const difference = (now, before, fields) => Object.fromEntries(fields.map(field => [field, (now?.[field] ?? 0) - (before?.[field] ?? 0)]));
const deltaRows = (now, before, key, fields) => {
  const left = new Map(now.map(row => [row[key], row]));
  const right = new Map(before.map(row => [row[key], row]));
  return [...new Set([...left.keys(), ...right.keys()])].map(value => ({ [key]: value, ...difference(left.get(value), right.get(value), fields) }));
};
const delta = previous ? {
  ...difference(current, previous, ['totalIssues', 'totalOpen', 'totalClosed']),
  byType: deltaRows(current.byType, previous.byType, 'type', ['total', 'open', 'closed']),
  byAuthor: deltaRows(current.byAuthor, previous.byAuthor, 'author', ['total', 'open', 'closed', 'bug', 'task', 'feature', 'unknown'])
} : null;
const comparison = { hasPrevious: previous !== null, previousWeekStart: config.previousWeekStart, previousPeriod: config.previousPeriod, delta };
const compact = stats => ({ totalIssues: stats.totalIssues, totalOpen: stats.totalOpen, totalClosed: stats.totalClosed, byType: stats.byType, byAuthor: stats.byAuthor });
const aiInput = { repository: current.repository, period: current.period, current: compact(current), previous: previous ? compact(previous) : null, comparison };
return [{ json: { ...current, weekStart: config.weekStart, comparison, aiInput } }];

const stats = $json;
const snapshot = { schemaVersion: 1, repository: stats.repository, weekStart: stats.weekStart, period: stats.period, totalIssues: stats.totalIssues, totalOpen: stats.totalOpen, totalClosed: stats.totalClosed, byType: stats.byType, byAuthor: stats.byAuthor };
return { json: { tableRow: { repository: stats.repository, week_start: stats.weekStart, period_start: stats.period.start, period_end: stats.period.end, total_issues: stats.totalIssues, total_open: stats.totalOpen, total_closed: stats.totalClosed, stats_json: JSON.stringify(snapshot) } } };

